/* Offline presentation. All empirical records are immutable exports in data.js.
 * Merge scenarios and counterfactuals are presentation fixtures, never experiments. */
(() => {
'use strict';
const D = window.CALITREE_DATA;
const app = document.getElementById('app');
const labels = ['no', 'partial', 'yes'];
const stages = ['System map', 'Inputs & labels', 'Selection policies', 'Decision check sets', 'Evidence & meaning', 'Batch calibration', 'Merge laboratory', 'Frozen inference', 'Results & boundaries'];
const subtitles = ['From an edited image to a traceable judgment', 'One edit, three inputs, one reference', 'Selection happens at several different boundaries', 'Make the instruction physically testable', 'Observe first. Interpret relative to the request.', 'Learn a reusable rule, then freeze it', 'A proposal becomes a parent only after validation', 'Follow the twelve cases through the saved policy', 'Separate what works from what is still a hypothesis'];
const notes = [
  'CaliTree is a judge-calibration system. It evaluates an already generated edit. The editing model’s image is the judge’s input; the judge outputs a satisfaction label and trace. The solid path is the current M1 + v8 research implementation. The amber branch is the proposed semantic hierarchy.',
  'These are twelve real development sources, four in each reference class. The reference is a released AURORA mean binned at 0.5 and 1.5. It is neither a majority vote nor a label for individual checks. The final fifty are excluded. Historical exposure means these twelve cannot support a fresh-test claim.',
  'Ask which object is being selected. Data selection chooses source-disjoint cases. Candidate selection chooses a fitted policy. Routing selects a policy at inference without access to labels. Merge ranking selects a proposal to evaluate. These policies have different information boundaries.',
  'The check set is case-specific, while the satisfaction policy is reusable. Every question binds a target, reference, role, polarity, dependencies, and content identity. A relocation instruction can require the same instance; an addition permits a new instance. A check saying true is not necessarily a success: collateral damage expects false.',
  'The observer answers the exact compiled questions against SOURCE then EDITED. The later text-only interpretation explains whether the recorded physical change reaches the requested endpoint and whether collateral effects matter. It does not see labels or images. Valid binding protects provenance, not perceptual truth.',
  'A local batch supplies examples for supervised fitting. High local agreement demonstrates fitting capacity. It does not establish transfer. Historical v16 local rules and the current pooled v8 policy are different experiments. V8 chooses a portable rule language and above-90% local fit, then prunes an explicit contradiction; it was not selected for held-out accuracy.',
  'Everything measured in this laboratory is a synthetic teaching fixture. The old prompt-tree library implements guarded merges and residual promotion. Applying a similar idea to the new semantic-rule hierarchy is M5–M9 future work. A parent learns from the full original source union, not the successful subset or a vote of child predictions.',
  'The current v8 deployment artifact is one pooled rule tree, not a learned hierarchy of local experts. This screen executes that exact tree over exported Boolean facts. A new case would require instruction compilation, image observation, and text interpretation. Replay needs none of those calls. The decision-tree branches are predicate tests, not new model calls.',
  'Keep three claims separate: local fitting capacity, portability of rule syntax, and statistical transfer. The 44/48 number is local fit. This twelve-case replay is historically exposed development evidence. Merging, fresh final accuracy, and repeated-extraction robustness remain unestablished. A model disagreement is not a reason to delete a reference or a case.'
];
const state = {stage: 0, caseIndex: 0, check: null, notes: true, revealed: false, tab: 'current', selection: 'candidate', merge: 'accept', replay: 0, playing: false, sandbox: null, flowStep: 3};
let timer = null;
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const title = s => String(s).replaceAll('_',' ').replace(/^./,c=>c.toUpperCase());
const label = n => n < 0 ? 'unresolved' : labels[n];
const badge = (s, cls='') => `<span class="tag ${esc(cls)}">${esc(s)}</span>`;
const outcome = n => badge(title(typeof n === 'number' ? label(n) : n),typeof n === 'number' ? label(n) : n);
const pct = n => (n*100).toFixed(1)+'%';
const current = () => D.cases[state.caseIndex];
const btn = (text, action, value, cls='') => `<button class="${cls}" data-action="${action}" ${value == null ? '' : `data-value="${esc(value)}"`}>${text}</button>`;
const tabs = (items, action, selected) => `<div class="tabs" role="group">${items.map(([id,name])=>btn(esc(name),action,id,id===selected?'active':'')).join('')}</div>`;
const io = (input, output) => `<div class="io"><div><label>Input</label>${input}</div><span class="arrow">→</span><div><label>Output</label>${output}</div></div>`;
const details = (name,obj) => `<details><summary>${esc(name)}</summary><pre>${esc(JSON.stringify(obj,null,2))}</pre></details>`;
function casebar() {return `<div class="casebar"><span class="case-label">Follow a case</span>${D.cases.map((c,i)=>btn(c.case,'case',i,i===state.caseIndex?'active':'')).join('')}</div>`;}
function pair(c, compact=false) {return `<div class="pair">${[['source_image','SOURCE · original'],['edited_image','EDITED · model output']].map(([key,text])=>`<figure><img src="${esc(c.images[key])}" alt="${esc(c.case+' '+text+' for '+c.instruction)}" ${compact?'style="height:170px"':''}><figcaption>${text}</figcaption></figure>`).join('')}</div>`;}
function facts(c) {return c.features.features;}
function execute(features) {
  if(!features) return {prediction:-1, trace:[],reason:'missing_evidence'};
  if(!features.meaning_available) return {prediction:-1, trace:[],reason:'missing_semantic_interpretation'};
  let node=D.policy.tree; const trace=[];
  while(node.feature) {const value=features[node.feature];trace.push({feature:node.feature,value});node=node[value?'true':'false'];}
  return {prediction:node.prediction,trace,reason:'portable_semantic_rule'};
}
function metrics(pred, refs) {
  const per=labels.map((_,k)=>{const support=refs.filter(y=>y===k).length, predicted=pred.filter(y=>y===k).length,correct=pred.filter((p,i)=>p===k&&refs[i]===k).length;return {support,predicted,correct,recall:support?correct/support:0,f1:support+predicted?2*correct/(support+predicted):0};});
  const correct=pred.filter((p,i)=>p===refs[i]).length;
  return {correct,total:refs.length,accuracy:correct/refs.length,macro_f1:per.reduce((s,c)=>s+c.f1,0)/3,unresolved:pred.filter(p=>p<0).length,per};
}
function stats(items) {return `<div class="stats">${items.map(([v,l])=>`<div class="stat"><strong>${v}</strong><span>${l}</span></div>`).join('')}</div>`;}
function overview() {
  const cards=[['01','▧','Case input','Instruction + SOURCE + EDITED',1],['02','⌘','Bound checks','Instruction → exact physical questions',3],['03','◉','Evidence','One visual observation of the pair',4],['04','≋','Meaning','Text-only, instruction-relative facts',4],['05','⑂','Frozen policy','Reusable deterministic rule execution',7]];
  return `<div class="panel dark"><div class="eyebrow" style="color:#acc9b1">The research question</div><h2 style="font-size:27px;margin:10px 0">Can a judge learn what humans mean by<br>“the requested edit was satisfied”?</h2><p class="muted" style="max-width:750px;font-size:13px">CaliTree turns local calibration examples into explicit evaluation policies. Each judgment can be traced back to the instruction, physical evidence, and a frozen rule.</p>${stats([['12','real development cases'],['90','bound physical questions'],['0','new model calls in this demo']])}</div>
  <div class="pipeline">${cards.map((c,i)=>(i?'<span class="arrow">→</span>':'')+`<button class="flowcard" data-action="stage" data-value="${c[4]}"><span class="flowindex">${c[0]} / INFERENCE</span><span class="flowicon">${c[1]}</span><strong>${c[2]}</strong><p>${c[3]}</p>${badge('Implemented')}</button>`).join('')}</div>
  <div class="grid2"><div class="panel"><div class="row"><h3>Training path</h3>${badge('Implemented')}</div><p class="small muted">48 labeled training sources → local/pooled candidates → bounded selection and semantic review → frozen v8 artifact.</p><div class="tokens">${['G1 · 12','G2 · 12','G3 · 12','G4 · 12'].map(x=>`<span class="token">${x}</span>`).join('')}<span class="token">pooled v8 · 44/48 local fit</span></div></div><div class="panel"><div class="row"><h3>Semantic hierarchy extension</h3>${badge('Illustrative · M5–M9','illustrative')}</div><p class="small muted">Rank local-policy pairs → recalibrate over their full union → validate router + replacement → keep a parent, children, or a forest.</p>${btn('Explore the merge laboratory →','stage',6,'ghost small')}</div></div>
  <div class="callout">Two different trees: the <b>rule tree</b> tests predicates inside one policy; the <b>policy hierarchy</b> organizes multiple specialists and merged parents. Current v8 exports the first. The new semantic hierarchy remains proposed.</div>`;
}
function dataset() {
  const c=current();
  return `${casebar()}<div class="grid2"><section class="panel"><div class="row"><h3>${c.case} · Benchmark example</h3>${badge('Recorded data')}</div><p class="case-title">“${esc(c.instruction)}”</p>${pair(c)}${btn('Enlarge images','images',null,'small ghost')}</section>
  <section class="panel"><h3>What enters and leaves the system?</h3><dl class="kv"><dt>Task input x</dt><dd>Instruction + source image + edited image</dd><dt>Generator output</dt><dd>The edited image, already produced by an editing model</dd><dt>Judge output ŷ</dt><dd>No / Partial / Yes, or Unresolved + evidence/rule trace</dd><dt>Reference y</dt><dd>${outcome(c.reference)} · released mean ${c.human_score.toFixed(4)} / 2</dd><dt>Reference use</dt><dd>Supervised fitting on training; scoring on development. Hidden from compilation, observation, interpretation, and runtime rule execution.</dd></dl><div class="numberline"><div><b>No</b><br>mean &lt; 0.5</div><div><b>Partial</b><br>0.5 ≤ mean &lt; 1.5</div><div><b>Yes</b><br>mean ≥ 1.5</div></div><p class="small muted">Released aggregate means, not individual votes. “Unresolved” is a system abstention, not a fourth reference label.</p>${details('Inspect case identity & reference',{case:c.case,source_group:c.source_group,human_score:c.human_score,reference:c.reference,image_hashes:c.image_hashes})}</section></div>
  <section class="panel" style="margin-top:18px"><h3>The study split</h3><div class="splitstrip"><div><strong>48</strong>Training<span>4 original batches × 12 sources</span></div><div><strong>12</strong>Development<span>These examples · 4 per class</span></div><div><strong>50</strong>Reserved final<span>Excluded from this demo</span></div></div><p class="small muted">Source-disjoint across study partitions. The 12 have historical research exposure. The final reservation is study-relative; historical exposure is disclosed in the M0 report.</p></section>
  <h3>The complete twelve-case set</h3><div class="casegrid">${D.cases.map((x,i)=>`<button class="casecard ${i===state.caseIndex?'active':''}" data-action="case" data-value="${i}"><img src="${esc(x.images.edited_image)}" alt="${esc(x.case+' edited image')}" loading="lazy"><strong>${x.case}</strong><div class="instruction">${esc(x.instruction)}</div>${outcome(x.reference)}</button>`).join('')}</div>`;
}
function selection() {
  const which=state.selection;
  const content={
    data:`${badge('Recorded protocol')}<h2 style="margin-top:14px">Select cases by source, not by output row</h2><div class="flowlane"><div class="nodebox"><strong>Source identities</strong><span class="muted">Decoded pixels + dataset lineage</span></div><span class="arrow">→</span><div class="nodebox"><strong>Fixed partitions</strong><span class="muted">48 training / 12 development / 50 reserved</span></div><span class="arrow">→</span><div class="nodebox"><strong>Balanced dev slice</strong><span class="muted">4 No + 4 Partial + 4 Yes</span></div></div><p class="small">A source group remains in one partition even when it has multiple editor outputs or file encodings. Keep extraction failures and missing records in the original denominator.</p><div class="callout">Labels can stratify the dataset at design time. They cannot route a new case or decide which evidence to observe at runtime.</div>`,
    candidate:`${badge('Current v8 · implemented')}<h2 style="margin-top:14px">Choose a reusable fitted policy</h2><ol class="small"><li>Search a fixed whitelist of portable semantic predicates, with bounded depth and minimum source support.</li><li>Qualify by <b>strictly greater than 90% local accuracy</b> over all 48 rows, including the missing observation.</li><li>Prefer larger minimum source support, then fewer nodes, shallower depth, more correct training cases, and stable profile name.</li><li>Review the selected rule tree for explicit written contradictions; prune the identified Yes exception.</li></ol><div class="callout">The selected fit is <b>${esc(D.selected_profile)}</b> at 46/48. Semantic review yields the recommended <b>44/48</b> deployment policy with 14 terminal rules. Held-out accuracy was not this selection objective.</div>${candidateTable()}`,
    routing:`${badge('Version-specific')}<h2 style="margin-top:14px">Choose the policy available to a new case</h2><div class="grid2"><div class="nodebox"><strong>Current reviewed v8</strong><p class="small">One pooled policy; no specialist router. Follow its predicate branches using frozen semantic facts.</p>${badge('Demo executes this')}</div><div class="nodebox"><strong>Existing routed-local baseline</strong><p class="small">Instruction-derived scope predicates; qualify specialists outside their fitting sources; use a declared pooled fallback. Evidence-dependent routing is a separate experimental extension.</p>${badge('Implemented experiment','historical')}</div></div><div class="callout amber">In the proposed hierarchy, scope, overlap precedence, mixed operations, unsupported scopes, and unresolved fallback must be frozen and validated together. Batch membership, true label, and “pick the most favorable expert answer” are prohibited runtime selectors.</div><p class="small muted">The legacy prompt-tree route_prompt additionally supports semantic embedding thresholds and routing-eligible children. That is a different strategy from the current portable semantic rule tree.</p>`,
    merge:`${badge('New semantic hierarchy · proposed','illustrative')}<h2 style="margin-top:14px">Select which pair is worth recalibrating</h2><ol class="small"><li>Compare reusable roles, dependencies, and condition structure.</li><li>Probe cross-policy behavior on training/development sources; distinguish shared correct decisions from shared mistakes.</li><li>Consider complementary errors that a pooled parent could repair.</li><li>Rank a bounded set of pairs with deterministic ties.</li><li>Fit and validate the parent before changing the active hierarchy.</li></ol><div class="callout amber">Semantic similarity proposes a merge. It cannot accept a merge. Two policies making the same mistake are not evidence of compatibility.</div><p class="small">Legacy builder options include semantic complete-link and behavioral complete-link ranking. Do not present those existing prompt-tree mechanisms as a completed M5 implementation for the new semantic-rule pipeline.</p>`
  };
  return `${tabs([['data','Dataset sampling'],['candidate','Candidate policy'],['routing','Inference routing'],['merge','Merge proposals']],'selection',which)}<section class="panel">${content[which]}</section>${io('Allowed selection inputs depend on the boundary','Frozen manifest, policy, route, or candidate pair + provenance')}`;
}
function candidateTable() {
  return `<div class="tablewrap"><table><thead><tr><th>Search profile</th><th>Local correct</th><th>Nodes</th><th>&gt;90%?</th><th>Selection</th></tr></thead><tbody>${Object.entries(D.candidates).map(([k,v])=>`<tr class="${k===D.selected_profile?'selected':''}"><td class="mono">${esc(k)}</td><td>${v.metrics.correct}/48</td><td>${v.nodes}</td><td>${v.eligible?'Qualifies':'Below floor'}</td><td>${k===D.selected_profile?'Selected before review':'Retained comparison'}</td></tr>`).join('')}</tbody></table></div>`;
}
function checks() {
  const c=current(),list=c.program.checks,selected=list.find(k=>k.id===state.check)||list[0];
  return `${casebar()}<p class="case-title">${c.case} · ${esc(c.instruction)}</p>${io('Instruction only; no images, labels, or prior verdicts',`${list.length} bound questions + requirement/dependency graph`)}
  <div class="check-layout"><section class="panel"><h3>The decision check set</h3><p class="small muted">Click a question to inspect its exact contract.</p><div class="checklist">${list.map(k=>`<button class="checkbtn ${k.id===selected.id?'active':''}" data-action="check" data-value="${esc(k.id)}">${badge(title(k.role),'unknown')} <code>${esc(k.id)}</code><span class="checkquestion">${esc(k.question)}</span></button>`).join('')}</div></section>
  <section class="panel"><div class="row"><h3>Question · ${esc(selected.id)}</h3>${badge('Bound artifact')}</div><p style="font-size:18px">${esc(selected.question)}</p><dl class="kv">${[['Instruction span',selected.source_quote],['Role / kind',title(selected.role)+' / '+title(selected.kind)],['Target',selected.target],['Reference',selected.reference],['Applicability',selected.applicability_condition],['Expected answer',selected.expected_state],['Dependencies',selected.dependencies.join(', ')||'None'],['Absence polarity',selected.absence_when],['Source anchor',selected.absence_source_anchor],['Question SHA-256',`<code>${esc(selected.check_ref)}</code>`]].map(([k,v])=>`<dt>${k}</dt><dd>${k==='Question SHA-256'?v:esc(v)}</dd>`).join('')}</dl><div class="callout">A <b>case-specific physical question</b> can name an object. The <b>learned policy</b> cannot use that object name, exact instruction, source ID, or image hash as its decision condition.</div>${details('All requirements & authorized changes',{requirements:c.program.requirements,contract:c.program.contract})}</section></div>
  <section class="panel" style="margin-top:18px"><h3>Six roles prevent different facts from collapsing together</h3><div class="tablewrap"><table><tbody>${[['outcome','The requested physical endpoint'],['identity','Original-instance correspondence when the task needs it'],['preservation','Expected continuity; does not count as affirmative progress'],['intermediate','A concrete configuration toward a linked requested endpoint'],['collateral_disappearance','An unrelated source entity disappearing'],['collateral_deformation','An unrelated structure, size, shape, or topology changing']].map(([k,v])=>`<tr><td>${badge(title(k),'unknown')}</td><td>${v}</td></tr>`).join('')}</tbody></table></div><p class="small muted" style="margin-top:10px">Required Not Applicable becomes an applicability diagnostic with an unknown effective state. Absence requires source anchoring and adequate edited coverage when an original object must be identified.</p></section>`;
}
function evidence() {
  const c=current(),entries=Object.values(c.record.checks),k=entries.find(x=>x.id===state.check)||entries.find(x=>x.role==='outcome')||entries[0];
  const obs=k.observation;
  return `${casebar()}<p class="case-title">${c.case} · ${esc(c.instruction)}</p>${io('Bound program + ordered SOURCE / EDITED pair','Raw/effective physical states → text-only semantic interpretation')}
  <div class="grid2"><section class="panel">${pair(c,true)}<h3 style="margin-top:15px">Recorded physical answers</h3><div class="tablewrap"><table><thead><tr><th>Question</th><th>Raw</th><th>Effective</th><th>Expected</th></tr></thead><tbody>${entries.map(x=>`<tr class="${x.id===k.id?'selected':''}"><td>${btn(esc(x.id),'check',x.id)}<br><span class="small muted">${title(x.role)}</span></td><td>${esc(x.asserted_state)}</td><td>${esc(x.state)}</td><td>${esc(x.expected_state)}</td></tr>`).join('')}</tbody></table></div></section>
  <section class="panel"><div class="row"><h3>${esc(k.id)} · evidence</h3>${badge('Cached model observation')}</div><p class="small">${esc(k.question)}</p><div class="evidencebox"><b>Source</b>${esc(obs.source_evidence)}</div><div class="evidencebox"><b>Edited</b>${esc(obs.edited_evidence)}</div><div class="evidencebox"><b>Comparison</b>${esc(obs.comparison)}</div><dl class="kv"><dt>Anchor / coverage</dt><dd>${esc(obs.source_anchor)} / ${esc(obs.edited_coverage)}</dd><dt>Diagnostics</dt><dd>${esc(k.diagnostics.join('; ')||'No normalization diagnostics for this check')}</dd></dl><div class="callout">Physical <code>true / false / unknown / not_applicable</code> are distinct from satisfaction <b>No / Partial / Yes</b>. A collateral check expecting false is satisfied by false.</div></section></div>
  <section class="panel" style="margin-top:18px"><div class="row"><h3>Instruction-relative interpretation</h3>${badge('Cached text-only model pass')}</div><p class="small muted">Receives the instruction and cached physical record. No images, dataset references, or earlier satisfaction verdicts.</p>${Object.entries(c.interpretation.requirements).map(([id,r])=>`<div class="evidencebox"><b>Requirement ${esc(id)}</b><div class="tokens">${['progress','endpoint_gap','retention_need','identity_materiality','collateral_materiality','evidence_consistency'].map(f=>`<span class="token">${title(f)}: ${esc(r[f].replaceAll('_',' '))}</span>`).join('')}</div><p style="margin:14px 0 0">${esc(r.explanation)}</p></div>`).join('')}<div class="callout amber">Model-produced facts can be wrong or disputed. H03’s mug contour, for example, is a recorded materiality dispute. Matching hashes prove attachment to a question and image pair; they do not prove visual truth.</div>${details('Inspect normalized features & diagnostics',{features:c.record.features,diagnostics:c.record.diagnostics})}</section>`;
}
function calibration() {
  const t=state.tab;
  return `${tabs([['current','Current v8 policy'],['local','Four local batches · v16'],['constrained','Earlier 12-case local learner'],['prompt','Prompt-tree optimization']],'tab',t)}${t==='current'?`<div class="grid2"><section class="panel"><div class="row"><h3>Fit against dataset reference labels</h3>${badge('Implemented · v8')}</div><div class="flowlane" style="grid-template-columns:1fr"><div class="nodebox"><strong>Training examples</strong>48 original sources; four collection batches; missing M1 observation retained</div><div class="nodebox"><strong>Portable semantic vocabulary</strong>Any/all physical predicates + instruction-relative meaning + operation flags</div><div class="nodebox"><strong>Bounded tree selection & review</strong>Above-90% local floor → support/complexity preference → contradiction pruning</div></div>${stats([['44/48','reviewed local agreement'],['14','terminal rules'],['13','used semantic predicates']])}<p class="small muted">The initial collection batch is not automatically a deployment branch. V8 is a pooled rule tree. Training IDs and supporting examples live in audit artifacts, outside its executable deployment artifact.</p>${btn('Inspect candidate selection →','selection-stage',null,'small')}</section><section class="panel"><h3>The saved portable rule tree</h3><p class="small muted">Expand branches. These are abstract evidence predicates, not object or instruction lookups.</p><div class="policytree">${renderTree(D.policy.tree)}</div></section></div><div class="callout amber">44/48 = local fitting capacity. It is not final accuracy or proof of statistical transfer. One missing training observation remains Unresolved in the denominator; no case was relabeled to improve fit.</div>`:t==='local'?localBatches():t==='prompt'?promptOptimization():constrained()}`;
}
function promptOptimization() {
  return `<section class="panel"><div class="row"><h3>Optimize → decompose → check → aggregate → validate</h3>${badge('Implemented modular path','historical')}</div><p class="small">The prompt-tree implementation learns rubric prompts. This is a different fitting mechanism from v8’s portable semantic rule search.</p>${io('Seed rubric + selected leaf fit cases + fit references','Measured optimized prompt + compiled policy + decision sets + validation artifact')}<div class="grid2"><div><h3>Optimizer plans</h3><table><tbody>${[['TextGrad','Textual-gradient feedback and bounded prompt updates'],['GEPA','Reflective candidate search through an isolated worker'],['Sequential plans','TextGrad → GEPA or GEPA → TextGrad'],['Best of both','Independent proposals from the same seed'],['Evaluate only','Retain and measure the supplied prompt']].map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td></tr>`).join('')}</tbody></table><div class="callout">Retain the seed. Select by fit <b>balanced accuracy</b>, then raw accuracy, then earlier candidate. The current v8 selection policy instead uses its local-accuracy floor and support/complexity ordering.</div></div><div><h3>Two-way decomposition</h3><div class="nodebox"><strong>Rubric → policy</strong>Compile the selected evaluation rubric separately from the instruction.</div><div class="nodebox" style="margin-top:10px"><strong>Instruction → check plan</strong>Bind what must be inspected in this case.</div><div class="nodebox" style="margin-top:10px"><strong>Evidence + policy → verdict</strong>Structured two_way executes a bounded policy DSL. two_way_vision uses semantic model aggregation over observed conditions; it is not the deterministic DSL.</div><p class="small muted" style="margin-top:12px">Fit labels may inform optimization. Reserved-validation and final-test labels do not enter optimizer/reflection calls. Judge usage and optimizer completion-token budgets are recorded separately.</p></div></div></section><section class="panel"><h3>Inspectable stage artifacts</h3><div class="tokens">${['optimization','compilation','instruction_decomposition','evidence_checks','aggregation','validation'].map(s=>`<span class="token">${s}</span>`).join('')}</div><p class="small" style="margin-top:15px">The canvas can run through a stage, freeze a completed immutable artifact, or rerun from a boundary. Prompt, strategy, model/template identity, instruction, question, image-byte and target bindings prevent an incompatible pin from silently executing. Recomputing metrics uses saved predictions with zero model calls.</p><p class="small muted">Leaf/merge artifacts preserve scope IDs, served IDs, correct IDs, ancestor lineage, policy hashes, plans, observations, predictions, budgets, and acceptance history. A successfully merged node does not automatically become the global fallback.</p></section>`;
}
function renderTree(node,path='root',depth=0) {
  if('prediction' in node) return `<div class="treeleaf">→ ${outcome(node.prediction)}</div>`;
  return `<details class="treenode ${depth===0?'root':''}" ${depth<1?'open':''}><summary>${esc(D.policy.predicate_descriptions[node.feature])}</summary><div class="treebranch">TRUE ↓</div>${renderTree(node.true,path+'.true',depth+1)}<div class="treebranch">FALSE ↓</div>${renderTree(node.false,path+'.false',depth+1)}</details>`;
}
function localBatches() {
  return `<div class="callout">This tab shows the <b>historical v16 teacher-distilled local experiment</b>, not v8. Each G batch contains 12 sources. The local rules fit teacher predictions; dataset reference agreement is reported separately. V8 later fits dataset references directly.</div><div class="grid2">${D.local_groups.map(g=>`<section class="panel"><div class="row"><h3>${g.name} · local reusable policy</h3>${badge('Historical measured fit','historical')}</div>${stats([[`${g.metrics.correct}/12`,'dataset reference agreement on its own batch']])}${['yes','partial'].map(l=>`<div class="rule"><b>${title(l)} if</b><br>${g.policy[l].map(clause=>clause.map(a=>`${esc(a.fact.replaceAll('_',' '))} = ${esc(a.test)}`).join('<br>AND ')).join('<br>OR<br>')}</div>`).join('')}<p class="small muted">Otherwise No, subject to the historical evaluator’s uncertainty bounds. Maximum 3 atoms/clause and 3 clauses/boundary; positive-clause support ≥2 source cases.</p></section>`).join('')}</div><section class="panel" style="margin-top:18px"><h3>Why merge local policies?</h3><p class="small">A local shortcut can fit its own cases and fail elsewhere. The saved v16 policies scored 6/12, 9/12, 9/12, and 8/12 respectively on the shared development set under their original evidence path. Pooling broader support may expose unsupported exceptions; a hierarchy can retain distinctions a common parent loses.</p><p class="small muted">Those scores come from the historical v16 transfer report, not the M1/v8 replay shown in this demo. Four policies evaluated on the same twelve sources still provide twelve independent evaluation examples.</p></section>`;
}
function constrained() {
  return `<section class="panel"><div class="row"><h3>Small anonymous monotone rule grammar</h3>${badge('Earlier implemented baseline','historical')}</div><p class="small">The earlier LocalEvidenceRuleCalibrator fits and scores the same 12 cached single-call evidence records. It is a separate local fitting diagnostic.</p><div class="grid2"><div><h3>Allowed questions</h3>${['Source preserved?','Every core condition has progress?','Every core condition complete?','Every constraint has progress?','Every constraint complete?'].map(x=>`<div class="rule">${x}</div>`).join('')}</div><div><h3>Search policy</h3><ol class="small"><li>At most two learned levels, three split nodes, four leaves.</li><li>Each learned leaf has ≥2 distinct unguarded source cases.</li><li>Protect fixed-policy No; retain unknown evidence as Unresolved.</li><li>Learned leaves are Partial or Yes; better fulfillment cannot reduce the label.</li><li>Maximize same-batch correct, then fewer splits and fewer changes from the original policy.</li></ol><div class="callout amber">These fixed No/monotonicity restrictions belong to this earlier baseline. They were not reinstated as universal label gates in the newer v8 learner.</div></div></div><p class="small muted">A separate EvidenceBatchCalibrator uses multinomial logistic regression with categorical/numeric evidence and TF-IDF text, selecting regularization by stratified CV on a separate 36-case calibration batch. It is a statistical baseline, not a semantic rule hierarchy.</p></section>`;
}
function mergeFixture(kind) {
  const refs=Array.from({length:kind==='support'?12:36},(_,i)=>i%3);
  const baseline=refs.slice();
  [0,4,8,15,19].filter(i=>i<refs.length).forEach(i=>baseline[i]=(refs[i]+1)%3);
  const parent=baseline.slice();
  if(kind==='reject') {for(let i=0;i<refs.length;i++)if(refs[i]===1)parent[i]=2;}
  else if(kind==='accept'||kind==='support') {[0,4].forEach(i=>parent[i]=refs[i]);}
  const scope=Array.from({length:24},(_,i)=>`F${String(i+1).padStart(2,'0')}`);
  const residual=kind==='partial'?scope.slice(20):[];
  return {refs,baseline,parent,scope,residual,b:metrics(baseline,refs),p:metrics(parent,refs)};
}
function merges() {
  const f=mergeFixture(state.merge),kind=state.merge;
  const enough=f.p.per.every(x=>x.support>=8),partialGuard=f.p.per[1].recall>=f.b.per[1].recall;
  const accepted=enough&&partialGuard&&f.p.macro_f1>=f.b.macro_f1&&f.p.correct>=f.b.correct-1;
  const status=!enough?'Insufficient evidence':accepted?'Accept illustrative replacement':'Reject illustrative replacement';
  return `<div class="callout amber"><b>Illustrative teaching fixtures throughout this screen.</b> Synthetic F01–F24 are training examples; synthetic V01–V36 are source-disjoint validation examples. No H01–H12 labels select a merge. The new semantic M5–M9 hierarchy is not implemented or empirically validated.</div>
  ${tabs([['accept','Accepted parent'],['reject','Rejected regression'],['partial','Residual promotion'],['support','Insufficient support']],'merge',kind)}
  <div class="grid2"><section class="panel"><div class="row"><h3>Pool the complete descendant scope</h3>${badge('Synthetic','illustrative')}</div><div class="mergegraph"><div class="mergechildren"><div class="nodebox"><strong>Leaf A</strong>12 original source cases<br><span class="muted">identity + endpoint conditions</span></div><div class="nodebox"><strong>Leaf B</strong>12 original source cases<br><span class="muted">progress + collateral conditions</span></div></div><div class="connector">→</div><div class="nodebox"><strong>Candidate parent P</strong><p class="small">Fit against all <b>24 original reference labels</b>, including descendant failures. Child conditions seed search; outputs are not voted.</p>${badge(kind==='partial'?'20/24 fit · 4 residual':'24/24 fit',kind==='partial'?'partial':'unknown')}</div></div><div class="tokens">${f.scope.map(id=>`<span class="token ${f.residual.includes(id)?'residual':''}">${id}</span>`).join('')}</div><p class="small muted" style="margin-top:12px">Full scope stays 24 even if only 20 assignments move to a parent. A later merge must still include all 24 original sources. Overlapping lineage is deduplicated.</p>${kind==='partial'?'<div class="callout">Legacy modular merge mechanics permit a partial parent with residual assignments on measured promoted leaves. “Partial merge” is topology/fit coverage; it is different from the satisfaction label Partial. This fixture combines those existing mechanics with an illustrative future semantic replacement.</div>':''}<div class="nodebox"><strong>Frozen routing after decision</strong>${accepted?(kind==='partial'?'Parent P serves its supported scope; residual specialist branches remain. Runtime scope is observable; training membership is audit-only.':'Use validated parent P on its supported domain; retain the pooled fallback outside it.'):'Keep A and B active; preserve the rejected/unsupported candidate and its history.'}</div></section>
  <section class="panel"><div class="row"><h3>Validate the routed system</h3>${badge('Synthetic validation','illustrative')}</div><p class="small muted">${f.refs.length} separate sources · ${f.refs.length/3} per label. Candidate parent + router are compared with the same existing routed baseline.</p><table><thead><tr><th>Measure</th><th>Before</th><th>After</th></tr></thead><tbody>${[['Accuracy',pct(f.b.accuracy),pct(f.p.accuracy)],['Correct / all',`${f.b.correct}/${f.b.total}`,`${f.p.correct}/${f.p.total}`],['Macro-F1',f.b.macro_f1.toFixed(3),f.p.macro_f1.toFixed(3)],['Partial recall',pct(f.b.per[1].recall),pct(f.p.per[1].recall)],['Resolved coverage',pct(1-f.b.unresolved/f.b.total),pct(1-f.p.unresolved/f.p.total)],['Active rule complexity','14 units',kind==='partial'?'12 units (parent + residuals)':'10 units']].map(x=>`<tr><td>${x[0]}</td><td>${x[1]}</td><td>${x[2]}</td></tr>`).join('')}</tbody></table><div class="gates">${[['Bound artifacts & full lineage union match',true],['Same validation sources; permitted routing inputs',true],['Macro-F1 and Partial recall do not decrease',f.p.macro_f1>=f.b.macro_f1&&partialGuard],['Coverage does not decrease',true],['Accuracy loss ≤1 case; no protected class/scope loss >1',f.p.correct>=f.b.correct-1&&f.p.per.every((p,i)=>p.correct>=f.b.per[i].correct-1)],['Improvement, or strict complexity reduction without metric loss',f.p.correct>f.b.correct||f.p.correct===f.b.correct&&f.p.macro_f1>=f.b.macro_f1],['At least 8 examples per class and protected scope',enough]].map(([name,ok])=>`<div class="gate ${ok?'':'fail'}"><span class="mark">${ok?'✓':'×'}</span>${name}</div>`).join('')}</div><div class="result ${accepted?'yes':!enough?'partial':'no'}"><div><span class="small">Fixture decision</span><br><b>${status}</b></div></div></section></div>
  <section class="panel" style="margin-top:18px"><h3>What exists today, and what this proposes</h3><div class="tablewrap"><table><thead><tr><th>System</th><th>Mechanism</th><th>Status</th></tr></thead><tbody><tr><td>Legacy prompt-tree / modular builder</td><td>Joint synthesis, refinement, full descendant-scope validation, reserved guard, accepted/partial/rejected nodes, measured residual promotion. Default historical covered threshold ≥80%; full fit is 100%.</td><td>${badge('Implemented')}</td></tr><tr><td>Current semantic M1 + v8</td><td>Bound questions, physical evidence, meaning projection, and one frozen pooled portable rule tree.</td><td>${badge('Implemented research')}</td></tr><tr><td>New semantic hierarchy M5–M9</td><td>Reusable scope discovery, pair proposals, full-union parent fitting, replacement validation, iterative hierarchy and frozen final comparison.</td><td>${badge('Proposed','illustrative')}</td></tr></tbody></table></div><p class="small muted" style="margin-top:12px">The proposed hierarchy’s eight-per-class/scope support and regression allowances are roadmap starting defaults, not guarantees or universal legacy settings. A high fit score alone cannot establish an accepted semantic merge.</p></section>`;
}
function traceView(result) {
  return `<div class="trace">${result.trace.map((t,i)=>`<div class="traceitem ${t.value?'':'false'}"><span class="branch">${t.value?'TRUE':'FALSE'}</span><div><span class="small muted">Predicate ${i+1}</span><br>${esc(D.policy.predicate_descriptions[t.feature])}<br><code class="muted">${esc(t.feature)}</code></div></div>`).join('')}</div><div class="result ${label(result.prediction)}"><div><span class="small">Frozen rule output</span><br><strong>${title(label(result.prediction))}</strong></div>${badge('No model call')}</div>`;
}
function flowDetail(c,pred) {
  if(state.flowStep===0)return `<h3>1 · Instruction → bound program</h3><p class="small muted">Input: instruction only. Output: ${c.program.checks.length} questions. This compiler never sees reference labels.</p>${c.program.checks.map(k=>`<div class="rule">${badge(title(k.role),'unknown')} <code>${esc(k.id)}</code><p style="margin:8px 0 0">${esc(k.question)}</p></div>`).join('')}`;
  if(state.flowStep===1)return `<h3>2 · Images + program → observations</h3><p class="small muted">One SOURCE-first presentation. Effective states preserve dependencies, applicability, and absence safeguards.</p><table><thead><tr><th>Check</th><th>Physical state</th><th>Expected</th></tr></thead><tbody>${Object.values(c.record.checks).map(k=>`<tr><td>${esc(k.id)}<br><span class="muted small">${title(k.role)}</span></td><td>${esc(k.state)}</td><td>${esc(k.expected_state)}</td></tr>`).join('')}</tbody></table>`;
  if(state.flowStep===2)return `<h3>3 · Evidence → instruction-relative meaning</h3><p class="small muted">Text-only interpretation; no images, target labels, or prior verdicts.</p>${Object.entries(c.interpretation.requirements).map(([id,r])=>`<div class="evidencebox"><b>${esc(id)}</b>${['progress','endpoint_gap','identity_materiality','collateral_materiality'].map(k=>`<p><span class="muted">${title(k)}:</span> ${esc(title(r[k]))}</p>`).join('')}<p>${esc(r.explanation)}</p></div>`).join('')}`;
  if(state.flowStep===4)return `<h3>5 · Prediction + reference → evaluation</h3>${traceView(pred)}<div class="evidencebox"><b>Reference used only for scoring</b>${outcome(c.reference)} · released mean ${c.human_score.toFixed(4)} / 2<p style="margin-top:12px">${label(pred.prediction)===c.reference?'Agreement on this recorded development source.':'Disagreement retained. Inspect evidence, interpretation, and policy separately before assigning a cause.'}</p></div>`;
  return `<h3>4 · Project facts → ${pred.trace.length} predicate tests</h3>${traceView(pred)}`;
}
function inference() {
  const c=current(),pred=execute(facts(c)),rows=D.cases.slice(0,state.replay);
  const chosen=state.sandbox,fiction=chosen?execute({...facts(c),[chosen]:!facts(c)[chosen]}):null;
  return `${casebar()}${tabs([['0','1 · Compile checks'],['1','2 · Observe images'],['2','3 · Interpret evidence'],['3','4 · Execute policy'],['4','5 · Score prediction']],'flow',String(state.flowStep))}<div class="grid2"><section class="panel"><div class="row"><h3>${c.case} · follow one case</h3>${badge('Exact v8 replay')}</div><p class="case-title">${esc(c.instruction)}</p>${pair(c,true)}<div class="flowlane" style="grid-template-columns:1fr;margin-bottom:0"><div class="nodebox"><strong>1 · Compile</strong>${c.program.checks.length} instruction-bound questions</div><div class="nodebox"><strong>2 · Observe + interpret</strong>Cached physical states and instruction-relative meaning</div><div class="nodebox"><strong>3 · Project + execute</strong>Portable Boolean predicates → deterministic saved tree</div></div><div class="callout">Fresh case: 1 instruction-only compilation + 1 visual observation + 1 text-only interpretation. This replay: <b>zero calls</b>. No reference label enters this rule traversal.</div><button data-action="reveal" class="small" ${state.flowStep<3?'disabled':''}>${state.revealed?'Hide reference':'Reveal reference after prediction'}</button>${state.revealed&&state.flowStep>=3?`<div style="margin-top:12px">Reference ${outcome(c.reference)} · mean ${c.human_score.toFixed(4)}<br><span class="small muted">${label(pred.prediction)===c.reference?'Agreement on this recorded case.':'Disagreement is preserved; inspect observations, meaning, and rule conditions separately.'}</span></div>`:''}</section>
  <section class="panel">${flowDetail(c,pred)}<p class="small muted" style="margin-top:15px">Policy artifact <code>${esc(D.policy.artifact_ref.slice(0,20))}…</code></p>${state.flowStep===3?`<div class="whatif">${badge('Synthetic counterfactual','illustrative')}<p style="margin-top:10px">Flip one predicate to see how the frozen tree responds. This is a rule-level probe; it does not alter the source evidence or represent a coherent re-observation.</p><select id="sandbox-select" aria-label="Predicate to flip"><option value="">Choose a predicate…</option>${Object.keys(D.policy.predicate_descriptions).map(k=>`<option value="${esc(k)}" ${k===chosen?'selected':''}>${esc(D.policy.predicate_descriptions[k])}</option>`).join('')}</select>${fiction?`<p style="margin:12px 0 0">${facts(c)[chosen]?'True → False':'False → True'} · synthetic output ${outcome(fiction.prediction)}</p>${details('Synthetic decision trace',fiction.trace)}`:''}</div>`:''}</section></div>
  <section class="panel" style="margin-top:18px"><div class="row"><div><h3>Replay all twelve cases</h3><p class="small muted">Replay reveals saved cases in order. It does not fit, call a model, or select a policy.</p></div><div class="tools">${btn(state.playing?'Pause':'Run twelve','play',null,'primary small')}${btn('Reset','reset-replay',null,'small')}</div></div><div class="progress">${D.cases.map((_,i)=>`<i class="${i<state.replay?'done':''}"></i>`).join('')}</div>${rows.length?`<table><thead><tr><th>Case</th><th>Instruction</th><th>Prediction</th><th>Reference</th><th>Agreement</th></tr></thead><tbody>${rows.map((x,i)=>`<tr class="replayrow ${i===rows.length-1?'just':''}"><td>${btn(x.case,'case',i)}</td><td>${esc(x.instruction)}</td><td>${outcome(x.prediction.prediction)}</td><td>${outcome(x.reference)}</td><td>${label(x.prediction.prediction)===x.reference?'✓':'Disagreement'}</td></tr>`).join('')}</tbody></table>`:'<div class="reveal-placeholder">Ready · 12 historically exposed development cases</div>'}</section>`;
}
function resultPage() {
  const pred=D.cases.map(c=>c.prediction.prediction),refs=D.cases.map(c=>labels.indexOf(c.reference)),m=metrics(pred,refs),diag=metrics(D.cases.map(c=>c.diagnostic.prediction),refs);
  return `<div class="grid2"><section class="panel"><div class="row"><h3>Current v8 · demo development replay</h3>${badge('Computed offline')}</div>${stats([[`${m.correct}/12`,'full-denominator agreement'],[m.macro_f1.toFixed(3),'macro-F1'],[`${12-m.unresolved}/12`,'resolved outputs']])}<div class="confusion"><span></span>${['No','Partial','Yes','Unres.'].map(x=>`<span class="axis">${x}</span>`).join('')}${labels.map((y,k)=>`<span class="axis">Ref ${title(y)}</span>${[0,1,2,-1].map(p=>{const n=pred.filter((v,i)=>v===p&&refs[i]===k).length;return `<span class="cell ${p===k?'diag':n?'err':''}">${n}</span>`;}).join('')}`).join('')}</div><p class="small muted" style="margin-top:12px">Rows: reference. Columns: prediction. Unresolved cases remain in every original denominator.</p><div class="callout amber">These twelve sources have historical exposure. This replay is a newly assembled demo diagnostic of the frozen v8 artifact, not an archived v8 held-out result or a final-test claim.</div></section>
  <section class="panel"><h3>Different numbers answer different questions</h3><table><thead><tr><th>Measurement</th><th>Result</th><th>Meaning</th></tr></thead><tbody><tr><td>Reviewed v8 on training</td><td>44/48</td><td>Local fitting capacity</td></tr><tr><td>M1 fixed readout on these 12</td><td>${diag.correct}/12; ${diag.unresolved} unresolved</td><td>Uncalibrated evidence diagnostic</td></tr><tr><td>V8 on these 12</td><td>${m.correct}/12</td><td>Historically exposed development replay</td></tr><tr><td>New semantic merges</td><td>No empirical score</td><td>Illustrated future work</td></tr><tr><td>Reserved final fifty</td><td>Not evaluated here</td><td>No final-test inference or export</td></tr></tbody></table><p class="small muted" style="margin-top:16px">AURORA references can be noisy, and generated observations can be wrong. A mismatch does not identify its cause. Uncertain annotation review, when explicitly recorded, is separate from valid Partial labels and unknown visual observations.</p></section></div>
  <section class="panel" style="margin-top:18px"><h3>All cases, all disagreements retained</h3><div class="tablewrap"><table><thead><tr><th>Case</th><th>Instruction</th><th>Ref</th><th>M1 diagnostic</th><th>V8 replay</th></tr></thead><tbody>${D.cases.map((c,i)=>`<tr><td>${btn(c.case,'open-inference',i)}</td><td>${esc(c.instruction)}</td><td>${outcome(c.reference)}</td><td>${outcome(c.diagnostic.prediction)}</td><td>${outcome(c.prediction.prediction)} ${label(c.prediction.prediction)===c.reference?'✓':''}</td></tr>`).join('')}</tbody></table></div></section>
  <div class="statusgrid"><section class="panel"><h3>Implementation boundaries</h3>${[['Implemented research','M1 bound evidence, v8 semantic interpretation/projection/runtime, local fitting and offline restoration.',''],['Implemented in legacy/modular path','Prompt optimization, policy compilation, guarded multi-child merges, partial promotion, scope/served lineage and stage artifacts.','historical'],['Illustrative / proposed','M5–M9 semantic pair ranking, full-union parent learning, router-aware validation and iterative policy hierarchy.','illustrative'],['Unestablished','Large-corpus transfer, final-set performance, repeated/paraphrased extraction robustness.','unknown']].map(([a,b,c])=>`<p>${badge(a,c)}<br><span class="small">${b}</span></p>`).join('')}</section><section class="panel links"><h3>Source ledger</h3><p class="small muted">Repository-relative source paths below identify the saved records. The export includes their SHA-256 identities for verification. No downloads, API calls, new fitting, or final-test records are needed.</p>${D.provenance.map(p=>`<p><code>${esc(p)}</code><br><code class="muted">${esc((D.source_hashes||{})[p]||'')}</code></p>`).join('')}${details('Portable deployment artifact',D.policy)}</section></div>`;
}
const renderers=[overview,dataset,selection,checks,evidence,calibration,merges,inference,resultPage];
function render() {
  const stage=state.stage;
  app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><svg viewBox="0 0 32 36" fill="none" aria-hidden="true"><path d="M16 32V18M16 23L6 15M16 18L26 10M16 12V5" stroke="#c7ddbc" stroke-width="2"/><circle cx="6" cy="12" r="4" fill="#a7c996"/><circle cx="26" cy="7" r="4" fill="#a7c996"/><circle cx="16" cy="5" r="4" fill="#e1ebc9"/></svg>CaliTree</div><p class="eyebrow">An end-to-end walkthrough</p><nav class="nav" aria-label="Presentation chapters">${stages.map((name,i)=>`<button data-action="stage" data-value="${i}" class="${i===stage?'active':''}" ${i===stage?'aria-current="step"':''}><span class="num">${String(i+1).padStart(2,'0')}</span>${name}</button>`).join('')}</nav><div class="sidebottom"><strong>Research snapshot · Oct 15, 2026</strong>12 real development cases<br>Illustrative semantic merges<br>100% offline replay</div></aside><main class="main"><header class="topbar"><span class="breadcrumb">RESEARCH DEMO &nbsp;/&nbsp; ${esc(stages[stage])}</span><div class="tools"><span class="offline"><i class="dot"></i>Offline · no API calls</span>${btn(state.notes?'Hide speaker notes':'Speaker notes','notes',null,'ghost')}${btn(document.body.classList.contains('presenting')?'Exit present':'Present','present',null,'ghost')}</div></header><div class="content"><div class="heading"><div><div class="eyebrow">${String(stage+1).padStart(2,'0')} / ${stages.length} · ${esc(stages[stage])}</div><h1>${subtitles[stage]}</h1></div>${badge(stage===6?'Illustrative merge fixtures':'Code-backed research snapshot',stage===6?'illustrative':'')}</div><p class="intro">${['Explore the current system from inputs to decisions, then examine how local policies could become a validated hierarchy.','A source image and an edit instruction go to the editing model. CaliTree judges the resulting edited image against that request.','Dataset sampling, fitted-model selection, inference routing, and merge proposal ranking use different information.','Inspect the real instruction-specific program. Check identities bind every later observation to the question it actually answers.','A physical observation is evidence. The calibration policy decides how that evidence maps to human satisfaction.','Local rules encode shared decision conditions. Selection history and training support stay visible, even after a policy is frozen.','Test acceptance, rejection, residual promotion, and insufficient support without presenting synthetic outcomes as experiments.','Traverse the actual saved v8 tree, reveal the reference afterward, and replay the full twelve-case sequence.','Inspect every prediction and keep implementation status, illustrative behavior, and measured performance distinct.'][stage]}</p>${renderers[stage]()}${state.notes?`<aside class="presenter"><span class="eyebrow">Speaker notes · ~1 minute</span>${notes[stage]}</aside>`:''}<footer class="footnav"><button data-action="prev" ${stage===0?'disabled':''}>← Previous</button><span class="muted">${stage+1} / ${stages.length} &nbsp;·&nbsp; <span class="kbd">←</span> <span class="kbd">→</span> chapters &nbsp; <span class="kbd">[</span> <span class="kbd">]</span> cases &nbsp; <span class="kbd">N</span> notes</span><button class="primary" data-action="next" ${stage===stages.length-1?'disabled':''}>Next chapter →</button></footer></div></main></div>`;
}
function stop() {clearInterval(timer);timer=null;state.playing=false;}
function setStage(n) {stop();state.stage=Math.max(0,Math.min(stages.length-1,Number(n)));state.sandbox=null;render();window.scrollTo({top:0,behavior:'instant'});}
function setCase(n) {state.caseIndex=(Number(n)+12)%12;state.check=null;state.revealed=false;state.sandbox=null;render();}
function images() {
  const modal=document.createElement('div');modal.className='modal';modal.setAttribute('role','dialog');modal.setAttribute('aria-modal','true');modal.setAttribute('aria-label','Source and edited image comparison');modal.innerHTML=`<div class="modal-inner"><div class="row"><h2>${current().case} · Image comparison</h2>${btn('Close ×','close-modal')}</div><p>${esc(current().instruction)}</p>${pair(current())}</div>`;app.append(modal);modal.querySelector('button').focus();modal.addEventListener('click',e=>{if(e.target===modal)modal.remove();});
}
app.addEventListener('click',e=>{
  const b=e.target.closest('button[data-action]');if(!b)return;
  const value=b.dataset.value;
  switch(b.dataset.action) {
    case 'stage':setStage(value);break;
    case 'prev':setStage(state.stage-1);break;
    case 'next':setStage(state.stage+1);break;
    case 'case':setCase(value);break;
    case 'check':state.check=value;render();break;
    case 'selection':state.selection=value;render();break;
    case 'tab':state.tab=value;render();break;
    case 'flow':state.flowStep=Number(value);state.sandbox=null;render();break;
    case 'merge':state.merge=value;render();break;
    case 'notes':state.notes=!state.notes;render();break;
    case 'present':document.body.classList.toggle('presenting');render();break;
    case 'images':images();break;
    case 'close-modal':b.closest('.modal').remove();break;
    case 'selection-stage':state.selection='candidate';setStage(2);break;
    case 'open-inference':state.caseIndex=Number(value);state.check=null;state.revealed=false;setStage(7);break;
    case 'reveal':state.revealed=!state.revealed;render();break;
    case 'reset-replay':stop();state.replay=0;render();break;
    case 'play':
      if(state.playing){stop();render();break;}
      if(state.replay===12)state.replay=0;
      state.playing=true;
      function tick(){state.caseIndex=state.replay;state.flowStep=3;state.check=null;state.sandbox=null;state.revealed=false;state.replay++;if(state.replay===12)stop();render();}
      tick();if(state.playing)timer=setInterval(tick,1200);break;
  }
});
app.addEventListener('change',e=>{if(e.target.id==='sandbox-select'){state.sandbox=e.target.value||null;render();}});
document.addEventListener('keydown',e=>{
  if(e.target.closest('select,input,textarea')||e.ctrlKey||e.metaKey||e.altKey)return;
  if(e.key==='Escape'){document.querySelector('.modal')?.remove();return;}
  if(document.querySelector('.modal'))return;
  if(e.key==='ArrowRight'){e.preventDefault();setStage(state.stage+1);}
  if(e.key==='ArrowLeft'){e.preventDefault();setStage(state.stage-1);}
  if(e.key===']'){e.preventDefault();setCase(state.caseIndex+1);}
  if(e.key==='['){e.preventDefault();setCase(state.caseIndex-1);}
  if(e.key.toLowerCase()==='n'){state.notes=!state.notes;render();}
});
// A small public read-only hook supports parity verification without depending on UI text.
window.CaliTreeDemo=Object.freeze({execute,metrics,mergeFixture});
for(const c of D.cases) {
  const p=execute(facts(c));
  if(JSON.stringify(p.trace)!==JSON.stringify(c.prediction.trace)||p.prediction!==c.prediction.prediction)throw new Error('Exported policy replay mismatch: '+c.case);
}
render();
})();
